type FilterOption = "all" | "restaurant" | "attraction";
const filterOptionToLabelKeys = {
  all: "staffQueueDisplayShowAll",
  restaurant: "staffQueueDisplayShowRestaurants",
  attraction: "staffQueueDisplayShowAttractions",
} satisfies Record<FilterOption, LabelKey>;

type SortOption = "WaitTimeDescending" | "WaitTimeAscending" | "AlphabeticalAscending" | "AlphabeticalDescending";
const sortOptionToLabelKeys = {
  WaitTimeDescending: "staffQueueDisplaySortOrderLongestWaitTime",
  WaitTimeAscending: "staffQueueDisplaySortOrderShortestWaitTime",
  AlphabeticalAscending: "staffQueueDisplaySortOrderAlphabeticalAscending",
  AlphabeticalDescending: "staffQueueDisplaySortOrderAlphabeticalDescending",
} satisfies Record<SortOption, LabelKey>;

type QueueTimeEntry = StaffQueueDisplayRowProps & {
  key: string;
  queueTime: number;
};

export function waitTimeAsTimespan(waitTimeLabelWeb: string | undefined | null) {
  // Matches the first timespan in the format "X-Y" in the string ("X" and "Y" being numbers)
  // Might also match "-" if the timespan is unknown
  return waitTimeLabelWeb?.match(/[-\d]+/)?.[0];
}

function openingHoursForContentfulEntry(
  now: Date,
  contentfulId: string | undefined,
  schedules: Array<ContentfulSchedule>,
) {
  if (!contentfulId) return undefined;

  return schedules
    .flatMap((schedule) => {
      if (schedule.externalEntry?.externalEntryId === contentfulId) {
        return schedule.events;
      }
      return schedule.events?.filter(({ externalEntry }) => externalEntry?.externalEntryId === contentfulId) ?? [];
    })
    .find(
      (event) =>
        DateHelper.isEqualYYYYMMDD(event?.startDateAndTime, now) ||
        DateHelper.isEqualYYYYMMDD(event?.endDateAndTime, now),
    );
}

function labelizeClosedReason(now: Date, openingHours: ContentfulEvent | undefined): ClosedText | undefined {
  if (!openingHours) return undefined;

  const { endDateAndTime, startDateAndTime } = openingHours;

  if (DateHelper.isBefore(now, startDateAndTime)) {
    return {
      kind: "label",
      value: "staffQueueDisplayClosedNotOpenYet",
      interpolation: [DateHelper.toStringTimeHHMM(startDateAndTime)],
    };
  }
  if (DateHelper.isAfter(now, endDateAndTime)) {
    return {
      kind: "label",
      value: "staffQueueDisplayClosedAlreadyClosed",
      interpolation: [DateHelper.toStringTimeHHMM(endDateAndTime)],
    };
  }
  return undefined;
}

function getRelevantOperatingWindows(
  queueTimeItem: QueueTimeItem,
  now: Date,
  includeNonPublicWindows: boolean,
): string[] {
  const operatingTimes = orderBy(queueTimeItem.schedule?.today?.operatingTimes ?? [], "opensOn");
  const upcoming = operatingTimes
    .filter((ot) => !DateHelper.isAfter(now, ot.closesOn))
    .filter((ot) => includeNonPublicWindows || ot.isOpenToPublic);
  const windows = upcoming.length > 0 ? upcoming : operatingTimes.slice(-1);
  return windows.map(
    (ot) => `${DateHelper.toStringTimeHHMM(ot.opensOn)} - ${DateHelper.toStringTimeHHMM(ot.closesOn)}`,
  );
}

function queueTimeToRow(
  queueTimeItem: QueueTimeItem,
  now: Date,
  schedules: Array<ContentfulSchedule>,
  includeNonPublicWindows: boolean,
): QueueTimeEntry {
  const { attractionId, info, queueTime, queueTimeText, state } = queueTimeItem;
  const { title, contentful_id } = RideStore.getRideById(attractionId) ?? {};

  const openingHours = openingHoursForContentfulEntry(now, contentful_id, schedules);
  const closedText = labelizeClosedReason(now, openingHours);

  return {
    kind: "attraction",
    key: `attraction-${attractionId}`,
    name: title || attractionId.toString(),
    queueTime,
    queueTimeText,
    state: getDisplayState(state, queueTimeText) === "STOPPAGE" ? "closed" : "open",
    closedText: info ? { kind: "text", value: info } : closedText,
    openingWindows: getRelevantOperatingWindows(queueTimeItem, now, includeNonPublicWindows),
  };
}
function waitTimeToRow(waitTime: CustomerDisplayItem, now: Date, schedules: Array<ContentfulSchedule>): QueueTimeEntry {
  const { terminalId, status } = waitTime;
  const { preparingOrders, approximateWaitTime, waitTimeLabelWeb } =
    mapCustomerDisplayApiToCustomerDisplayWeb(waitTime);
  const { title, contentful_id } = RestaurantStore.getRestaurantsByTerminalId(terminalId) ?? {};

  const openingHours = openingHoursForContentfulEntry(now, contentful_id, schedules);
  const closedText = labelizeClosedReason(now, openingHours);

  return {
    kind: "restaurant",
    key: `restaurant-${terminalId}`,
    name: title || terminalId.toString(),
    ordersInqueue: preparingOrders?.length,
    queueTime: approximateWaitTime ?? -1, // Seems to be the default API value for unknown wait times
    queueTimeText: waitTimeAsTimespan(waitTimeLabelWeb) || "-",
    state: status === CustomerDisplayStatus.OFFLINE ? "closed" : "open",
    closedText,
  };
}

export type StaffQueueDisplayProps = {
  rideIds: Array<number>;
  terminalIds: Array<number>;
  // Used for testing/storybook purposes
  nowString?: string;
};
export function StaffQueueDisplay({ rideIds, terminalIds, nowString }: StaffQueueDisplayProps) {
  const { data: queueTimes } = useFetchAllQueueTimes({
    updateInterval: 60_000,
    includeEvents: true,
    includeHideForWeb: true,
  });
  const waitTimes = useParkFoodWaitTimes(terminalIds) ?? [];

  const [queueTimeFilter, setQueueTimeFilter] = useState<FilterOption>("all");
  const [checkedSettings, setCheckedSettings] = useState<Set<"hideStopped" | "includeNonPublicQueueTimes">>(new Set());
  const [sortOptionValue, setSortOption] = useState<SortOption>("WaitTimeDescending");
  const [sortOptionsExpanded, setSortOptionsExpanded] = useState(false);
  const [openingHours, setOpeningHours] = useState<Array<ContentfulSchedule>>([]);

  useEffect(() => {
    async function fetchOpeningHours() {
      const response = await ScheduleStore.getSchedulesForTypes(["OpeningHour"]);
      setOpeningHours(response || []);
    }
    fetchOpeningHours();
  }, []);

  const now = useMemo(() => {
    if (nowString) return createDate(nowString);
    return new Date();
  }, [nowString]);

  const setSortOptionAndUnexpand = (value: SortOption) => {
    setSortOption(value);
    setSortOptionsExpanded(false);
  };

  const filteredQueueTimes = queueTimes?.filter(({ attractionId }) => rideIds.includes(attractionId)) ?? [];

  const items = [
    ...filteredQueueTimes.map((qt) =>
      queueTimeToRow(qt, now, openingHours, checkedSettings.has("includeNonPublicQueueTimes")),
    ),
    ...waitTimes.map((wt) => waitTimeToRow(wt, now, openingHours)),
  ];

  return (
    <StaffQueueDisplayInner
      queueTimes={items}
      queueTimeFilter={queueTimeFilter}
      checkedSettings={checkedSettings}
      sortOptionValue={sortOptionValue}
      sortOptionsExpanded={sortOptionsExpanded}
      setFilter={setQueueTimeFilter}
      setSortOption={setSortOptionAndUnexpand}
      setSortOptionsExpanded={setSortOptionsExpanded}
      setCheckedSettings={setCheckedSettings}
    />
  );
}

const sortByTime = ({ state, queueTime }: QueueTimeEntry) => {
  if (state === "closed") return Number.POSITIVE_INFINITY;
  return queueTime;
};
const sortAlphabetically = ({ name }: QueueTimeEntry) => name.toLowerCase();

const sortBy = {
  AlphabeticalAscending: { sortFunction: sortAlphabetically, sortOrder: "asc" },
  AlphabeticalDescending: { sortFunction: sortAlphabetically, sortOrder: "desc" },
  WaitTimeAscending: { sortFunction: sortByTime, sortOrder: "asc" },
  WaitTimeDescending: { sortFunction: sortByTime, sortOrder: "desc" },
} as const satisfies Record<SortOption, unknown>;

export function StaffQueueDisplayInner({
  queueTimes,
  queueTimeFilter,
  sortOptionValue,
  sortOptionsExpanded,
  checkedSettings,
  setFilter,
  setSortOption,
  setSortOptionsExpanded,
  setCheckedSettings,
}: {
  queueTimes: QueueTimeEntry[];
  queueTimeFilter: FilterOption;
  sortOptionValue: SortOption;
  sortOptionsExpanded: boolean;
  checkedSettings: Set<"hideStopped" | "includeNonPublicQueueTimes">;
  setFilter: (value: FilterOption) => void;
  setSortOption: (value: SortOption) => void;
  setSortOptionsExpanded: (value: boolean) => void;
  setCheckedSettings: (value: Set<"hideStopped" | "includeNonPublicQueueTimes">) => void;
}) {
  const { t } = useTranslation();

  const filteredQueueTimes = queueTimes
    .filter(({ kind }) => {
      if (queueTimeFilter === "all") {
        return true;
      }
      return kind === queueTimeFilter;
    })
    .filter(({ state }) => {
      if (!checkedSettings.has("hideStopped")) {
        return true;
      }
      return state === "open";
    });
  const { sortFunction, sortOrder } = sortBy[sortOptionValue];
  const sortedQueueTimes = orderBy(filteredQueueTimes, sortFunction, sortOrder);

  // We should always show the closed items at the top of the list
  const closedQueueTimes = sortedQueueTimes.filter(({ state }) => state === "closed");
  const openQueueTimes = sortedQueueTimes.filter(({ state }) => state === "open");
  const processedQueueTimes = [...closedQueueTimes, ...openQueueTimes];

  return (
    <section className={styles.wrapper}>
      <h1 className="heading-m">{t("staffQueueDisplayHeader")}</h1>
      <div className={styles.filterRow}>
        <StyledRadioButtons
          radioItemClassName={styles.queueTimeFilterRadioButton}
          name="queueTimeFilter"
          options={Object.entries(filterOptionToLabelKeys).map(([key, value]) => ({ value: key, label: t(value) }))}
          onChange={(_name, value) => setFilter(value as FilterOption)}
          value={queueTimeFilter}
        />
        <CheckboxButtons
          variant="small"
          options={[
            {
              label: t("staffQueueDisplayHideClosed"),
              value: "hideStopped",
            },
            {
              label: t("staffQueueDisplayShowAllOpeningHours"),
              value: "includeNonPublicQueueTimes",
            },
          ]}
          value={[...checkedSettings].join(", ")}
          onChange={(_, value) => setCheckedSettings(new Set(value.split(", ")) as typeof checkedSettings)}
        />
      </div>
      <b>{t(filterOptionToLabelKeys[queueTimeFilter])}</b>
      <div className={styles.sortRow} data-expanded={sortOptionsExpanded}>
        <PrimaryButton
          isFullWidth
          label={t("staffQueueDisplaySort")}
          iconRightNew={sortOptionsExpanded ? "expand-less" : "expand-more"}
          size="medium"
          iconSize="xs"
          onClick={() => setSortOptionsExpanded(!sortOptionsExpanded)}
        />
        <ExpandableContent
          isExpanded={sortOptionsExpanded}
          removeChildrenWhenUnexpanded={true} // We want to remove the children when the content is not expanded to avoid hijacking the tab order
        >
          <StyledRadioButtons
            displayMode="VERTICAL"
            radioItemClassName={styles.sortRadioButton}
            radioItemsWrapperClassName={styles.sortRadioButtonWrapper}
            name="d"
            options={Object.entries(sortOptionToLabelKeys).map(([key, value]) => ({ value: key, label: t(value) }))}
            onChange={(_name, value) => setSortOption(value as SortOption)}
            value={sortOptionValue}
          />
        </ExpandableContent>
      </div>
      <div className={styles.queueTimes}>
        {processedQueueTimes?.map(({ key, ...queueTime }) => <StaffQueueDisplayRow key={key} {...queueTime} />)}
      </div>
      <PrimaryButton
        isFullWidth
        label={t("staffQueueDisplayScrollToTop")}
        onClick={() =>
          window.scrollTo({
            top: 0,
            behavior: "smooth",
          })
        }
      />
    </section>
  );
}

type ClosedText = { kind: "label"; value: LabelKey; interpolation: [string] } | { kind: "text"; value: string };

function getSubtitle(
  isClosed: boolean,
  closedText: ClosedText | undefined,
  ordersInqueue: number | undefined,
  openingWindows: string[] | undefined,
  t: TFunction,
): ReactNode {
  const windowsNode = openingWindows?.length ? openingWindows.join(", ") : null;

  if (isClosed) {
    let closedNode: ReactNode;
    if (closedText?.kind === "label") {
      closedNode = (
        <TranslationWithWrappers
          label={closedText.value}
          interpolation={closedText.interpolation}
          wrappers={{ 0: (s) => <b>{s}</b> }}
        />
      );
    } else {
      closedNode = closedText?.value ?? null;
    }
    if (closedNode && windowsNode)
      return (
        <>
          {closedNode}
          <br />
          {windowsNode}
        </>
      );
    return closedNode ?? windowsNode;
  }

  if (ordersInqueue !== undefined) {
    return t("staffQueueDisplayOrdersInQueue", [ordersInqueue]);
  }

  return windowsNode;
}

type StaffQueueDisplayRowProps = {
  kind: "attraction" | "restaurant";
  name: string;
  ordersInqueue?: number;
  queueTimeText: string;
  state: "open" | "closed";
  closedText?: ClosedText;
  openingWindows?: string[];
};
function StaffQueueDisplayRow({
  kind,
  name,
  ordersInqueue,
  queueTimeText,
  state,
  closedText,
  openingWindows,
}: StaffQueueDisplayRowProps) {
  const { t } = useTranslation();

  const isClosed = state === "closed";

  const subtitle = getSubtitle(isClosed, closedText, ordersInqueue, openingWindows, t);
  const closedClass = isClosed ? styles.closed : "";
  queueTimeText = isClosed ? t("staffQueueDisplayPlaceClosed") : queueTimeText;
  return (
    <>
      <div className={`${styles.place} ${closedClass}`}>
        <div className={styles.placeName}>
          <Icon name={kind === "attraction" ? "roller-coaster" : "restaurant"} size="l" />
          <b>{name}</b>
        </div>
        {subtitle && <span className="body-s">{subtitle}</span>}
      </div>
      <div className={`${styles.queueTime} ${closedClass}`}>
        <b>{queueTimeText}</b>
      </div>
    </>
  );
}
