const STATE_OK = 0;
export type DISPLAY_STATE = "STOPPAGE" | "NO_TIME_AVAILABLE" | "TIME_AVAILABLE";

export const getDisplayState = (state: number, queueTimeText?: string): DISPLAY_STATE => {
  if (state === STATE_OK && (!queueTimeText || queueTimeText === "0")) {
    return "NO_TIME_AVAILABLE";
  }

  if (state === STATE_OK && queueTimeText) {
    return "TIME_AVAILABLE";
  }

  //state !== STATE_OK
  return "STOPPAGE";
};
